module BS2Suite::HDDisplay
  class << self
    def menu_rows(scene)
      window=selected_window(scene);object=window && defined?(BS2QoL::Reference) && BS2QoL::Reference.object_for(window)
      return bs2099993_old_menu(scene) unless BS2Suite::CatalogUI.supported?(object)
      rows=[row('T',object.name)];lines=BS2Suite::CatalogUI.static_rows(object,actor_for(scene))
      if object.is_a?(RPG::EquipItem)
        view=equip_projection(actor_for(scene),object,scene);lines+=comparison(actor_for(scene),view) if view
      end
      rows+catalog_rows(object,lines,capacity-3)+[row('D','F7 — details')]
    end
  end
end if defined?(BS2Suite::HDDisplay)
