  alias repair099994_initialize initialize
  def initialize(*args)
    repair099994_initialize(*args)
    @sections=@sections.map do |rows|
      rows.map do |line|
        line.gsub(/(?:Техническая запись|Technical entry) state:(\d+)/) { BS2Suite::CatalogUI.state_name($1.to_i,language) }
      end.uniq
    end
  end
